// Programmatic Heap Snapshot Capture on High Memory Threshold
import v8 from 'node:v8';
import process from 'node:process';

export function setupMemoryGuard(thresholdMB = 1024) {
  setInterval(() => {
    const memory = process.memoryUsage();
    const heapUsedMB = memory.heapUsed / 1024 / 1024;

    if (heapUsedMB > thresholdMB) {
      console.warn(`🚨 Memory threshold exceeded: ${heapUsedMB.toFixed(2)}MB used. Generating diagnostic heap snapshot...`);

      const snapshotPath = v8.writeHeapSnapshot();
      console.log(`✅ Heap snapshot written to: ${snapshotPath}`);
      console.log('Inspect this file in Chrome DevTools -> Memory -> Load.');
    }
  }, 30000); // Check every 30s
}

// Bounded LRU Cache Pattern (Prevents Unbounded In-Memory Cache Leaks)
export class BoundedLRUCache {
  constructor(maxItems = 1000) {
    this.maxItems = maxItems;
    this.cache = new Map(); // Map preserves insertion order!
  }

  get(key) {
    if (!this.cache.has(key)) return undefined;
    // Re-insert to mark as most recently used
    const val = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, val);
    return val;
  }

  set(key, val) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.maxItems) {
      // Evict oldest entry (first item in Map iterator)
      const oldestKey = this.cache.keys().next().value;
      this.cache.delete(oldestKey);
    }
    this.cache.set(key, val);
  }
}

// Production Health Probes, Pino Logging & Graceful Connection Pool Lifecycle
import express from 'express';
import pino from 'pino';

// High-performance asynchronous structured logger
export const logger = pino({
  level: process.env.LOG_LEVEL || 'info',
  formatters: {
    level: (label) => ({ level: label.toUpperCase() })
  },
  redact: ['req.headers.authorization', 'req.body.password', 'req.body.creditCard']
});

const app = express();

// 1. Liveness Probe (Is Node process alive?)
app.get('/health/live', (req, res) => {
  res.status(200).json({ status: 'live', uptime: process.uptime() });
});

// 2. Readiness Probe (Are database pools connected?)
app.get('/health/ready', async (req, res) => {
  try {
    // Check database connection health
    // await db.ping();
    res.status(200).json({ status: 'ready', database: 'connected' });
  } catch (err) {
    logger.error('Readiness probe failed: Database disconnected', err);
    res.status(503).json({ status: 'unready', error: 'Database unavailable' });
  }
});

// 3. Graceful Connection Draining
export function registerGracefulShutdown(server, dbPool) {
  const shutdown = async (signal) => {
    logger.info(`Received ${signal}. Draining HTTP server and database pool...`);

    server.close(async () => {
      logger.info('HTTP server stopped accepting new requests.');
      try {
        await dbPool.end(); // Drain and close DB connection pool
        logger.info('Database pool drained cleanly. Exiting code 0.');
        process.exit(0);
      } catch (err) {
        logger.error('Error closing database pool:', err);
        process.exit(1);
      }
    });

    // Force exit after 10s timeout to prevent hanging
    setTimeout(() => {
      logger.error('Forced shutdown timeout reached. Exiting code 1.');
      process.exit(1);
    }, 10000).unref();
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

// System Design Capacity Estimation Template for Technical Screenings
export interface ScaleCalculations {
  dailyActiveUsers: number;
  operationsPerUser: number;
  peakMultiplier: number;
  payloadSizeBytes: number;
  retentionYears: number;
}

export function calculateSystemCapacity(inputs: ScaleCalculations) {
  const SECONDS_PER_DAY = 86400;
  const totalDailyOperations = inputs.dailyActiveUsers * inputs.operationsPerUser;

  // 1. Average & Peak RPS
  const averageRps = Math.round(totalDailyOperations / SECONDS_PER_DAY);
  const peakRps = Math.round(averageRps * inputs.peakMultiplier);

  // 2. Daily & 5-Year Storage Ingestion
  const dailyStorageBytes = totalDailyOperations * inputs.payloadSizeBytes;
  const dailyStorageGigabytes = (dailyStorageBytes / (1024 ** 3)).toFixed(2);
  const fiveYearStorageTerabytes = ((dailyStorageBytes * 365 * inputs.retentionYears) / (1024 ** 4)).toFixed(2);

  // 3. Network Bandwidth (Egress/Ingress)
  const networkBandwidthMegabytesPerSec = ((peakRps * inputs.payloadSizeBytes) / (1024 ** 2)).toFixed(2);

  return {
    averageRps,
    peakRps,
    dailyStorageGigabytes: `${dailyStorageGigabytes} GB/day`,
    fiveYearStorageTerabytes: `${fiveYearStorageTerabytes} TB (5 years)`,
    peakBandwidth: `${networkBandwidthMegabytesPerSec} MB/sec`
  };
}
